policies.inbound:






        application/json

      @("{\"error\":\"" + (string)context.Variables["callerName"] + " is not allowed to use the Microsoft Learn MCP server\"}")



<set-variable name="mcpTool" value="@{
    if (context.Request.Method != "POST") { return ""; }
    var body = context.Request.Body.As(preserveContent: true);
    return (string)body["method"] == "tools/call" ? (string)body["params"]["name"] : "";
}" />






        application/json


        @((string)context.Variables["mcpTool"])

      @{
          var body = context.Request.Body.As(preserveContent: true);
          var text = "API Management policy blocks the tool '" + (string)context.Variables["mcpTool"]
              + "' for " + (string)context.Variables["callerName"] + ".";
          return new JObject(
              new JProperty("jsonrpc", "2.0"),
              new JProperty("id", body["id"]),
              new JProperty("result", new JObject(
                  new JProperty("content", new JArray(new JObject(
                      new JProperty("type", "text"),
                      new JProperty("text", text)))),
                  new JProperty("isError", true)))).ToString();
      }
